package com.az.scicalc;
import android.app.Dialog;
import android.graphics.Color;
import android.graphics.drawable.ColorDrawable;
import android.view.*;
import android.widget.*;

final class DisplayMenus {
 static void percent(MainActivity app){
  Dialog dialog=new Dialog(app);ToolPage p=new ToolPage(app,"",()->{});LinearLayout content=new LinearLayout(app);content.setOrientation(1);content.setPadding(p.dp(18),p.dp(10),p.dp(18),0);content.setBackground(ToolPage.texture(app));
  TextView title=ToolPage.text(app,"⚠  百分比计算模式",22);content.addView(title,new LinearLayout.LayoutParams(-1,p.dp(60)));
  RadioGroup group=new RadioGroup(app);boolean[] relative={app.prefs.getBoolean("relativePercent",true)};
  String[] examples={"100 + 20％ = 120","100 + 20％ = 100.2"},notes={"百分比根据左侧的值计算。仅适用于加法和减法。","百分比通过除以 100 计算。"};
  for(int i=0;i<2;i++){final int n=i;RadioButton radio=new RadioButton(app);radio.setId(200+i);radio.setText(examples[i]);radio.setTypeface(UiFonts.REGULAR);radio.setTextSize(android.util.TypedValue.COMPLEX_UNIT_DIP,20);radio.setTextColor(ToolPage.TEXT);radio.setButtonTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{ToolPage.ACCENT,ToolPage.TEXT}));group.addView(radio,new RadioGroup.LayoutParams(-1,p.dp(52)));radio.setOnClickListener(v->{relative[0]=n==0;group.check(200+n);});TextView note=ToolPage.text(app,notes[i],16);note.setPadding(p.dp(15),0,0,p.dp(12));group.addView(note,new RadioGroup.LayoutParams(-1,-2));note.setOnClickListener(v->{relative[0]=n==0;group.check(200+n);});}
  group.check(relative[0]?200:201);content.addView(group);TextView ok=ToolPage.text(app,"确定",18);ok.setTextColor(ToolPage.ACCENT);ok.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);ok.setPadding(0,0,p.dp(12),0);content.addView(ok,new LinearLayout.LayoutParams(-1,p.dp(58)));ok.setOnClickListener(v->{app.prefs.edit().putBoolean("relativePercent",relative[0]).putBoolean("percentModeChosen",true).apply();app.applyPreferences();app.changed();dialog.dismiss();});dialog.setContentView(content);dialog.show();dialog.getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));dialog.getWindow().setLayout(Math.round(app.view.getWidth()*.82f),-2);
 }
 static void font(MainActivity app,java.util.function.IntConsumer action){ToolPage p=new ToolPage(app,"",()->{});LinearLayout menu=new LinearLayout(app);menu.setOrientation(1);menu.setBackground(ToolPage.rounded(app,ToolPage.BG,0));PopupWindow popup=new PopupWindow(menu,Math.round(app.view.getWidth()*.6f),-2,true);popup.setBackgroundDrawable(new ColorDrawable(ToolPage.BG));popup.setOutsideTouchable(true);popup.setElevation(p.dp(6));TextView title=ToolPage.text(app,"显示字体大小",22);title.setPadding(p.dp(16),0,0,0);menu.addView(title,new LinearLayout.LayoutParams(-1,p.dp(52)));
  String[] labels={"缩小","放大","重置","字体","计算器皮肤","声音与振动"},icons={"circleMinus","circlePlus","reset","font","palette","sound"};for(int i=0;i<labels.length;i++){if(i==3){TextView caption=ToolPage.text(app,"想要更多个性化设置吗？",16);caption.setTextColor(ToolPage.MUTED);caption.setPadding(p.dp(16),p.dp(8),0,0);menu.addView(caption,new LinearLayout.LayoutParams(-1,p.dp(44)));}final int n=i;LinearLayout row=new LinearLayout(app);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(ToolPage.icon(app,icons[i],labels[i],()->{popup.dismiss();action.accept(n);},.58f),new LinearLayout.LayoutParams(p.dp(66),p.dp(54)));TextView text=ToolPage.text(app,labels[i],22);row.addView(text,new LinearLayout.LayoutParams(0,-1,1));row.setOnClickListener(v->{popup.dismiss();action.accept(n);});menu.addView(row,new LinearLayout.LayoutParams(-1,p.dp(54)));}int[] location=new int[2];app.view.getLocationOnScreen(location);popup.showAtLocation(app.view,Gravity.TOP|Gravity.RIGHT,0,location[1]+Math.round(app.view.getHeight()*750/2400f));}
 static void angle(MainActivity app){
  Dialog dialog=new Dialog(app);ToolPage p=new ToolPage(app,"",()->{});LinearLayout content=new LinearLayout(app);content.setOrientation(1);content.setBackground(ToolPage.texture(app));LinearLayout header=new LinearLayout(app);header.setPadding(p.dp(16),0,p.dp(8),0);header.setGravity(Gravity.CENTER_VERTICAL);header.addView(ToolPage.text(app,"角度单位",22),new LinearLayout.LayoutParams(0,p.dp(60),1));header.addView(ToolPage.icon(app,"close","关闭角度单位",dialog::dismiss),new LinearLayout.LayoutParams(p.dp(36),p.dp(60)));content.addView(header);
  String[] labels={"RADIAN","DEGREE","GRADIAN"},examples={"Sin(Pi/2)=1","Sin(90)=1","Sin(100)=1"};int[] modes={1,0,2},selected={app.angleMode};java.util.ArrayList<RadioButton> radios=new java.util.ArrayList<>();
  for(int i=0;i<3;i++){final int n=i;LinearLayout row=new LinearLayout(app);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(p.dp(10),0,p.dp(16),0);RadioButton radio=new RadioButton(app);radio.setText(labels[i]);radio.setTextSize(android.util.TypedValue.COMPLEX_UNIT_DIP,17);radio.setTypeface(UiFonts.REGULAR);radio.setTextColor(ToolPage.TEXT);radio.setButtonTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{ToolPage.ACCENT,ToolPage.TEXT}));radio.setChecked(modes[i]==app.angleMode);radios.add(radio);row.addView(radio,new LinearLayout.LayoutParams(p.dp(130),-1));FormulaPreview example=new FormulaPreview(app,"",examples[i],false,ToolPage.TEXT,17,0);example.monospace();row.addView(example,new LinearLayout.LayoutParams(0,-2,1));Runnable choose=()->{selected[0]=modes[n];for(int j=0;j<radios.size();j++)radios.get(j).setChecked(j==n);};radio.setOnClickListener(v->choose.run());row.setOnClickListener(v->choose.run());example.setOnClickListener(v->choose.run());content.addView(row,new LinearLayout.LayoutParams(-1,p.dp(62)));}
  TextView ok=ToolPage.text(app,"确定",18);ok.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);ok.setPadding(0,0,p.dp(24),0);ok.setTextColor(ToolPage.ACCENT);content.addView(ok,new LinearLayout.LayoutParams(-1,p.dp(52)));ok.setOnClickListener(v->{app.prefs.edit().putBoolean("trigAngleChosen",true).apply();app.setAngle(selected[0]);dialog.dismiss();});dialog.setContentView(content);dialog.show();dialog.getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));dialog.getWindow().setLayout(Math.round(app.view.getWidth()*.87f),-2);
 }
}
